export const BASIC_PRESETS = {
  "ping_pong": "REM ============================================================\nREM 🏓 Clack-BASIC: Ultra-Fast Autonomes Ping-Pong\nREM ============================================================\n\nREM 1. Initialisierung: Einmalig Bildschirm leeren\nCLS\n\nREM Ball-Koordinaten (Startmitte)\nLET BX = 16\nLET BY = 16\nLET OLD_BX = 16\nLET OLD_BY = 16\nLET VX = 1\nLET VY = 1\n\nREM Paddle-Positionen (Hoehe 4 Pixel)\nLET LY = 14\nREM Rechtes Paddle\nLET RY = 14\nLET OLD_LY = 14\nLET OLD_RY = 14\n\nGAME_LOOP:\n    REM --- Alte Positionen gezielt loeschen (Zero Flicker & Turbo-Speed!) ---\n    PSET 1, OLD_LY, 0\n    PSET 1, OLD_LY + 1, 0\n    PSET 1, OLD_LY + 2, 0\n    PSET 1, OLD_LY + 3, 0\n    \n    PSET 30, OLD_RY, 0\n    PSET 30, OLD_RY + 1, 0\n    PSET 30, OLD_RY + 2, 0\n    PSET 30, OLD_RY + 3, 0\n    \n    PSET OLD_BX, OLD_BY, 0\n    \n    REM --- Neue Positionen zeichnen ---\n    PSET 1, LY, 1\n    PSET 1, LY + 1, 1\n    PSET 1, LY + 2, 1\n    PSET 1, LY + 3, 1\n    \n    PSET 30, RY, 1\n    PSET 30, RY + 1, 1\n    PSET 30, RY + 2, 1\n    PSET 30, RY + 3, 1\n    \n    PSET BX, BY, 1\n    \n    REM --- Alte Positionen merken ---\n    LET OLD_LY = LY\n    LET OLD_RY = RY\n    LET OLD_BX = BX\n    LET OLD_BY = BY\n    \n    REM --- Ball bewegen ---\n    LET BX = BX + VX\n    LET BY = BY + VY\n    \n    REM --- Bandenkollision oben / unten ---\n    IF BY <= 1 THEN\n        LET VY = 1\n    END IF\n    IF BY >= 30 THEN\n        LET VY = -1\n    END IF\n    \n    REM --- Paddle-Kollision Links (X=2) ---\n    IF BX <= 2 THEN\n        LET VX = 1\n    END IF\n    \n    REM --- Paddle-Kollision Rechts (X=29) ---\n    IF BX >= 29 THEN\n        LET VX = -1\n    END IF\n    \n    REM --- Autonome KI: Linkes Paddle folgt Ball ---\n    IF BY > LY + 1 THEN\n        IF LY < 27 THEN\n            LET LY = LY + 1\n        END IF\n    END IF\n    IF BY < LY + 1 THEN\n        IF LY > 1 THEN\n            LET LY = LY - 1\n        END IF\n    END IF\n    \n    REM --- Autonome KI: Rechtes Paddle folgt Ball ---\n    IF BY > RY + 1 THEN\n        IF RY < 27 THEN\n            LET RY = RY + 1\n        END IF\n    END IF\n    IF BY < RY + 1 THEN\n        IF RY > 1 THEN\n            LET RY = RY - 1\n        END IF\n    END IF\n    \n    GOTO GAME_LOOP\n",
  "mandelbrot_32x32": "REM ============================================================\nREM Clack-BASIC Mandelbrot 32x32 - Version ohne FOR\nREM\nREM WICHTIG:\nREM Keine FOR/NEXT-Schleifen. Der Clack-BASIC Compiler legt die\nREM FOR-Endwerte im Temp-Bereich 950..959 ab. Dieser Bereich wird\nREM fuer Ausdrucks-Temporaries zyklisch wiederverwendet; bei diesem\nREM komplexeren Programm wurden dadurch die Schleifengrenzen\nREM ueberschrieben.\nREM\nREM Festkomma: 1.0 = 32\nREM X: -67 .. +26  -> ca. -2.09 .. +0.81\nREM Y: -47 .. +46  -> ca. -1.47 .. +1.44\nREM 20 Iterationen pro Pixel\nREM ============================================================\n\nLET DA = 960\nLET CY = -47\nLET Y = 0\n\nY_LOOP:\n\nIF Y > 31 THEN\n    GOTO DONE\nEND IF\n\nLET CX = -67\nLET X = 0\nLET ROW = 0\n\nX_LOOP:\n\nIF X > 31 THEN\n    GOTO NEXT_Y\nEND IF\n\nREM z = 0\nLET ZX = 0\nLET ZY = 0\nLET I = 0\n\nITER_LOOP:\n\nREM Nach 20 Iterationen gilt der Punkt als innerhalb\nIF I > 19 THEN\n    GOTO PIXEL_IN\nEND IF\n\nREM Betraege der Komponenten\nLET X2 = ZX\nIF X2 < 0 THEN\n    LET X2 = -X2\nEND IF\n\nLET Y2 = ZY\nIF Y2 < 0 THEN\n    LET Y2 = -Y2\nEND IF\n\nREM Schneller Fluchttest: |Re(z)| > 2 oder |Im(z)| > 2\nREM 2.0 = 64 bei Scale 32\nIF X2 > 64 THEN\n    GOTO PIXEL_OUT\nEND IF\n\nIF Y2 > 64 THEN\n    GOTO PIXEL_OUT\nEND IF\n\nREM |ZX*ZY| sichern\nLET XY = X2 * Y2\n\nREM Quadrate wieder auf Scale 32 bringen\nLET X2 = X2 * X2\nLET X2 = X2 / 32\n\nLET Y2 = Y2 * Y2\nLET Y2 = Y2 / 32\n\nREM |z|^2 > 4 ?\nREM 4.0 = 128 bei Scale 32\nIF X2 + Y2 > 128 THEN\n    GOTO PIXEL_OUT\nEND IF\n\nREM 2*ZX*ZY / 32 = ZX*ZY / 16\nLET XY = XY / 16\n\nREM Vorzeichen von ZX*ZY rekonstruieren\nIF ZX < 0 THEN\n    IF ZY >= 0 THEN\n        LET XY = -XY\n    END IF\nELSE\n    IF ZY < 0 THEN\n        LET XY = -XY\n    END IF\nEND IF\n\nREM z(n+1) = z(n)^2 + c\nLET ZY = XY + CY\nLET ZX = X2 - Y2\nLET ZX = ZX + CX\n\nLET I = I + 1\nGOTO ITER_LOOP\n\n\nPIXEL_IN:\n\nREM Eine 1 in das 16-Bit-Zeilenwort schieben\nLET ROW = ROW SHL 1\nLET ROW = ROW + 1\nGOTO PIXEL_DONE\n\n\nPIXEL_OUT:\n\nREM Eine 0 in das 16-Bit-Zeilenwort schieben\nLET ROW = ROW SHL 1\n\n\nPIXEL_DONE:\n\nREM Hardware 32x32 Matrix Zuordnung:\nREM X=0..15  (Linke Haelfte)  -> Wort 1 (DA + 1)\nREM X=16..31 (Rechte Haelfte) -> Wort 0 (DA)\nIF X = 15 THEN\n    POKE DA + 1, ROW\n    LET ROW = 0\nEND IF\n\nIF X = 31 THEN\n    POKE DA, ROW\nEND IF\n\nLET X = X + 1\nLET CX = CX + 3\nGOTO X_LOOP\n\n\nNEXT_Y:\n\nLET Y = Y + 1\nLET CY = CY + 3\nLET DA = DA + 2\nGOTO Y_LOOP\n\n\nDONE:\n\nHALT\n",
  "graphics_demo": "REM ============================================================\nREM ⚡ Clack-BASIC: LED Matrix Grafik-Demo (32x32 / 64x64)\nREM Demonstrating CLS, LINE (Bresenham), PLOT, and PIXELMOVE\nREM ============================================================\n\nREM 1. Display leeren\nCLS\n\nREM 2. Rahmen zeichnen mit LINE\nLINE 0, 0 TO 31, 0, 1\nLINE 31, 0 TO 31, 31, 1\nLINE 31, 31 TO 0, 31, 1\nLINE 0, 31 TO 0, 0, 1\n\nREM 3. Diagonales Kreuz zeichnen\nLINE 0, 0 TO 31, 31, 1\nLINE 0, 31 TO 31, 0, 1\n\nREM 4. Einzelne Punkte setzen mit PLOT\nPLOT 16, 8, 1\nPLOT 16, 24, 1\n\nREM 5. Punkt verschieben mit PIXELMOVE\nPIXELMOVE 16, 8 TO 16, 9, 1\n\nEND\n",
  "math_test": "REM ============================================================\nREM ⚡ Clack-BASIC: Mathematik- & Logiktest\nREM ============================================================\n\nLET A = 25\nLET B = 14\n\nREM 1. Addition & Subtraktion\nLET C = A + B\nLET D = A - B\n\nREM 2. Multiplikation (16-Bit Shift & Add Subroutine)\nLET P = 12 * 7\n\nREM 3. Division & Modulo (16-Bit Restoring Division)\nLET Q = 100 / 8\nLET R = 100 MOD 8\n\nREM 4. Verzweigung\nIF P > 80 THEN\n    LET STATUS = 1\nELSE\n    LET STATUS = 0\nEND IF\n\nHALT\n",
  "data_read": "REM ============================================================\nREM ⚡ Clack-BASIC: DATA, READ & RESTORE Test\nREM ============================================================\n\nDATA 100, 200, 300, 400\n\nREAD A, B\nREAD C, D\n\nRESTORE\nREAD FIRST_AGAIN\n\nHALT\n",
  "matrix_bounce": "REM ============================================================\nREM ⚡ Clack-BASIC: Bouncing Pixel Animation (32x32 Matrix)\nREM ============================================================\n\nCLS\n\nLET X = 0\nLET Y = 0\nLET DX = 1\nLET DY = 1\n\nLOOP:\n    PSET X, Y, 0xFFFF\n    \n    LET X = X + DX\n    LET Y = Y + DY\n    \n    IF X >= 30 THEN\n        LET DX = -1\n    END IF\n    IF X <= 1 THEN\n        LET DX = 1\n    END IF\n    \n    IF Y >= 30 THEN\n        LET DY = -1\n    END IF\n    IF Y <= 1 THEN\n        LET DY = 1\n    END IF\n    \n    GOTO LOOP\n",
  "wurzel_sqr": "REM ============================================================\nREM ⚡ Clack-BASIC: Hardwarenahe Wurzelfunktion (SQR / SQRT)\nREM ============================================================\nREM 1. Ganzzahlige Quadratwurzel (8-Schritt Bit-by-Bit)\nLET R1 = SQR(64)       REM Ergibt 8\nLET R2 = SQR(100)      REM Ergibt 10\nLET R3 = SQRT(25)      REM Ergibt 5\n\nREM 2. Festkomma-Wurzel mit Nachkommastellen (Differenzextraktion)\nLET W2_1 = SQR(2, 1)   REM Ergibt 14  (1.4)\nLET W2_2 = SQR(2, 2)   REM Ergibt 141 (1.41)\nLET W3_2 = SQR(3, 2)   REM Ergibt 173 (1.73)\nLET W10_2 = SQR(10, 2) REM Ergibt 316 (3.16)\n\nHALT\n",
  "mandelbrot_64x64": "REM ============================================================\nREM ⚡ Clack-BASIC Mandelbrot 64x64 (Hochoptimiert)\nREM ============================================================\nREM Relaiscomputer von Dipl.-Ing. (FH) Peter Prikasky\nREM Architektur: 16-Bit Relais-CPU, 1024 Worte RAM\nREM Display: 64x64 LED-Matrix (Framebuffer: 768..1023, 256 Worte)\nREM\nREM Mathematische & architektonische Optimierungen:\nREM 1. SCREEN 64 Direktive:\nREM    Legt Variablen ab 700 und Temporaries ab 740 ab.\nREM    Damit bleibt der Framebuffer (768..1023) kollisionsfrei!\nREM 2. Symmetrie-Spiegelung an der reellen Achse (X-Achse):\nREM    Berechnung erfolgt nur fuer die obere Haelfte (Y=0..31).\nREM    Die gespiegelte Zeile 63-Y wird simultan ins Display\nREM    geschrieben -> Exakt 50% Rechenzeiteinsparung (2x Speedup)!\nREM 3. Unrolled Hardware-Bitshifts (SHR):\nREM    Ersetzt die langsame Divisions-Subroutine (__div) vollstaendig\nREM    durch 16-Bit Hardware-Rechtsshifts (SHR 6 = /64, SHR 5 = /32).\nREM    Spart ueber 800 Relais-Zyklen pro Pixel-Iteration!\nREM 4. Vorzeichen-Extraktion per Bitwise XOR:\nREM    LET S = ZX XOR ZY ersetzt 12 Vergleichs- und Verzweigungs-\nREM    befehle durch einen einzigen schnellen Vorzeichentest.\nREM 5. 16-Bit Block-POKE:\nREM    16 Pixel werden in ein Zeilenwort gepackt und mit einem\nREM    einzigen POKE-Befehl fuer Zeile Y und 63-Y geschrieben.\nREM ============================================================\n\nSCREEN 64\n\nREM Framebuffer-Zeiger:\nREM Obere Zeile Y=0:   DA  = 768\nREM Untere Zeile Y=63: DAS = 1020\nLET DA = 768\nLET DAS = 1020\n\nREM Y von -94 bis -1 bei Scale 64 (entspricht Im: -1.47 .. -0.02)\nLET CY = -94\nLET Y = 0\n\nY_LOOP:\nIF Y > 31 THEN\n    GOTO DONE\nEND IF\n\nREM X von -135 bis +54 bei Scale 64 (entspricht Re: -2.11 .. +0.84)\nLET CX = -135\nLET X = 0\nLET ROW = 0\nLET PA = DA\nLET PAS = DAS\n\nX_LOOP:\nIF X > 63 THEN\n    GOTO NEXT_Y\nEND IF\n\nREM Startwert z0 = 0\nLET ZX = 0\nLET ZY = 0\nLET I = 0\n\nITER_LOOP:\nIF I > 15 THEN\n    GOTO PIXEL_IN\nEND IF\n\nREM Betraege fuer Fluchttest und quadratische Terme\nLET X2 = ZX\nIF X2 < 0 THEN\n    LET X2 = -X2\nEND IF\nIF X2 > 128 THEN\n    GOTO PIXEL_OUT\nEND IF\n\nLET Y2 = ZY\nIF Y2 < 0 THEN\n    LET Y2 = -Y2\nEND IF\nIF Y2 > 128 THEN\n    GOTO PIXEL_OUT\nEND IF\n\nREM Skalierung via Hardware-Shifts (Scale 64: Quadrate / 64, Mischterm / 32)\nLET XY = (X2 * Y2) SHR 5\nLET X2 = (X2 * X2) SHR 6\nLET Y2 = (Y2 * Y2) SHR 6\n\nREM Fluchtradius |z|^2 > 4.0 (4.0 = 256 bei Scale 64)\nIF X2 + Y2 > 256 THEN\n    GOTO PIXEL_OUT\nEND IF\n\nREM Vorzeichen von ZX * ZY via XOR rekonstruieren\nLET S = ZX XOR ZY\nIF S < 0 THEN\n    LET XY = -XY\nEND IF\n\nREM z(n+1) = z(n)^2 + c\nLET ZY = XY + CY\nLET ZX = X2 - Y2\nLET ZX = ZX + CX\n\nLET I = I + 1\nGOTO ITER_LOOP\n\nPIXEL_IN:\nREM 1 in das 16-Bit Zeilenwort schieben (Punkt gehoert zur Menge)\nLET ROW = ROW SHL 1\nLET ROW = ROW + 1\nGOTO PIXEL_DONE\n\nPIXEL_OUT:\nREM 0 in das 16-Bit Zeilenwort schieben (Fluchtpunkt / Hintergrund)\nLET ROW = ROW SHL 1\n\nPIXEL_DONE:\nREM Alle 16 Pixel ein 16-Bit Wort in den Framebuffer schreiben\nREM (und gleichzeitig gespiegelt in die untere Bildhaelfte)\nIF (X AND 15) = 15 THEN\n    POKE PA, ROW\n    POKE PAS, ROW\n    LET PA = PA + 1\n    LET PAS = PAS + 1\n    LET ROW = 0\nEND IF\n\nLET X = X + 1\nLET CX = CX + 3\nGOTO X_LOOP\n\nNEXT_Y:\nLET Y = Y + 1\nLET CY = CY + 3\nLET DA = DA + 4\nLET DAS = DAS - 4\nGOTO Y_LOOP\n\nDONE:\nHALT\n"
};
